import {Button, Container, Image} from "react-bootstrap";
import "./NavPagesInformation.css"
import {Link, useNavigate} from "react-router-dom";
import {useEffect} from "react";
import {Trans, useTranslation} from "react-i18next";

export const ResearchPlatform = () => {
    const {t} = useTranslation();
    const navigate = useNavigate();

    const navigateToContact = () => {
        navigate('/contact');
    }
    return (
        <>
            <Container>

                <div className="text-start" id="researchPlatformPageContainer">
                    <h3 className="mt-3 fw-bold">{t('navbar_title.research_platform')}</h3>

                    <p className="mt-4 mb-0 fw-bold">{t('research_platform.section_1.title')}</p>
                    <p className="mb-0">{t('research_platform.section_1.paragraph_1')}</p>

                    <ul>
                        <li>{t('research_platform.section_1.bullet_pts.1')}</li>
                        <li>{t('research_platform.section_1.bullet_pts.2')}</li>
                        <li>{t('research_platform.section_1.bullet_pts.3')}</li>
                        <li>
                            {t('research_platform.section_1.bullet_pts.4')}
                            <Link
                                className="btn-link"
                                to={"https://pubs.aip.org/asa/jasa/article/147/3/EL252/997279/Development-of-the-Canadian-Digit-Triplet-Test-in"}
                                target="_blank">{t('research_platform.section_1.bullet_pts_4_link')}</Link>
                        </li>
                        <li>{t('research_platform.section_1.bullet_pts.4')}</li>
                    </ul>

                    {/* Image of the user interface and accessories */}
                    <Image className="w-100"
                           src="https://raw.githubusercontent.com/MelinaRochon/CDTT_lists/main/Script/Images/Research-interface-EN.jpg"
                           alt="Research Interface"></Image>

                    <p className="mt-4 mb-0 fw-bold">{t('research_platform.section_2.title')}</p>
                    <ul>
                        <li>{t('research_platform.section_2.bullet_pts.1')}</li>
                        <li>{t('research_platform.section_2.bullet_pts.2')}</li>
                        <li>{t('research_platform.section_2.bullet_pts.3')}</li>
                        <li>{t('research_platform.section_2.bullet_pts.4')}</li>
                        <li>{t('research_platform.section_2.bullet_pts.5')}</li>
                    </ul>

                    <p className="mt-4 mb-0">{t('research_platform.section_3.title')}</p>
                    <p className="mt-0 mb-0">{t('research_platform.section_4.title')}</p>

                    <p className="mt-4 mb-0 fw-bold">{t('research_platform.section_5.title')}</p>
                    <p className="m-0">
                        <Trans i18nKey="research_platform.section_5.paragraph_1" components={{
                            formLink: (
                                <Link className="btn-link"
                                      to={"https://view.officeapps.live.com/op/view.aspx?src=https%3A%2F%2Fraw.githubusercontent.com%2FMelinaRochon%2FCDTT_lists%2Frefs%2Fheads%2Fmain%2FScript%2FNon-commercial_EULA_(CDTT)_Request_Form.docx&wdOrigin=BROWSELINK"}
                                      target="_blank" />
                            ),
                            contactLink: (
                                <Link className="btn-link" to={"/contact"} />
                            )
                        }}/>
                    </p>
                </div>
            </Container>
        </>
    )
}