import {Button, Container} from "react-bootstrap";
import "./NavPagesInformation.css";
import MailTo from "./MailTo";
import {Link} from "react-router-dom";
import {Trans, useTranslation} from "react-i18next";

const Contact = () => {

    const {t} = useTranslation();

    return (
        <Container>
            <div className="text-start" id="contactPageContainer">
                <h3 className="mt-3 fw-bold">{t('navbar_title.contact')}</h3>

                <p className="mt-4 mb-0 fw-bold">{t('contact.section_1.title')}</p>
                <p className="mb-0">
                    {t('contact.section_1.name_1')}
                    <Link className="btn-link"
                          to={`mailto:${t('contact.section_1.email_1')}`}>{t('contact.section_1.email_1')}</Link>
                    <br/>
                    {t('contact.section_1.name_2')}
                    <Link className="btn-link"
                          to={`mailto:${t('contact.section_1.email_2')}`}>{t('contact.section_1.email_2')}</Link>
                    <br/>
                    {t('contact.section_1.name_3')}
                    <Link className="btn-link"
                          to={`mailto:${t('contact.section_1.email_3')}`}>{t('contact.section_1.email_3')}</Link>
                </p>

                <p className="mt-4 mb-0 fw-bold">{t('contact.section_2.title')}</p>
                <p className="mb-0">
                    {t('contact.section_2.name_1')}
                    <br/>
                    {t('contact.section_2.name_2')}
                </p>

                <p className="mt-5 fst-italic">{t('contact.rights')}</p>
            </div>
        </Container>
    )
}

export default Contact;