import {Button, Container} from "react-bootstrap";
import "./NavPagesInformation.css";
import {Link, useNavigate} from "react-router-dom";
import {Trans, useTranslation} from "react-i18next";

export const HomePage = () => {

    const {t} = useTranslation();
    const navigate = useNavigate();

    const navigateToResearchPlatform = () => {
        navigate('/researchPlatform');
    }
    const navigateToTest = () => {
        navigate('/test');
    }
    return (
        <>
            <Container>
                <div className="text-start" id="aboutPageContainer">
                    <h3 className="mt-3 fw-bold">{t('navbar_title.about')}</h3>
                    <p className="mt-4 mb-0">
                        <Trans i18nKey="about.paragraph_1" components={{
                            icraLink: (
                                <Link className="btn-link" to={"https://icra-audiology.org/"} target="_blank"/>
                            ),
                            multilangualSpeechLink: (
                                <Link className="btn-link" target="_blank"
                                      to={"https://www.tandfonline.com/doi/full/10.3109/14992027.2015.1030513"}/>
                            )
                        }}/>
                    </p>
                    <div className="d-flex flex-column align-items-start mt-2 mb-2">
                        <Link className="btn-link" to={"https://canadianaudiologist.ca/u-of-o-feature-4/"}
                              target="_blank">{t('about.link_1_title')}</Link>
                        <Link className="btn-link mb-1"
                              to={"https://pubs.aip.org/asa/jasa/article/147/3/EL252/997279/Development-of-the-Canadian-Digit-Triplet-Test-in"}
                              target="_blank">{t('about.link_2_title')}</Link>
                    </div>

                    <p>{t('about.paragraph_2.before_link_1')}
                        <Link className="btn-link"
                              to={"https://ccna-ccnv.ca/en/"}
                              target="_blank">{t('about.paragraph_2.link_1_title')}</Link>
                        {t('about.paragraph_2.between_link_1_and_link_2')}
                        <Link className="btn-link" to={"https://www.clsa-elcv.ca/"}
                              target="_blank">{t('about.paragraph_2.link_2_title')}</Link>
                        {t('about.paragraph_2.after_link_2')}
                    </p>

                    <ul>
                        <li>
                            <Trans i18nKey="about.bullet_pts_1" components={{
                                goToLink: (
                                    <Link className="btn-link" to={"/researchPlatform"} />
                                )
                            }}/>
                        </li>
                        <li>
                            <Trans i18nKey="about.bullet_pts_2" components={{
                                goToLink: (
                                    <Link className="btn-link" to={"/test"} />
                                )
                            }}/>
                        </li>
                    </ul>
                </div>
            </Container>
        </>
    );
}